import { Buffer } from 'node:buffer';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative, resolve } from 'node:path';
import process from 'node:process';
import { fileURLToPath, URLSearchParams } from 'node:url';

const commitMutation = `mutation($input: CreateCommitOnBranchInput!) {
  createCommitOnBranch(input: $input) {
    commit { oid signature { isValid } }
  }
}`;

const execute = (command, args, options = {}) =>
  execFileSync(command, args, { maxBuffer: 16 * 1024 * 1024, ...options });

function github(method, endpoint, body) {
  const args = ['api', '--method', method, endpoint];
  if (body) args.push('--input', '-');
  const output = execute('gh', args, {
    input: body ? JSON.stringify(body) : undefined,
  }).toString();
  const result = output ? JSON.parse(output) : null;
  if (result?.errors?.length) throw new Error(JSON.stringify(result.errors));
  return result;
}

// Dependencies are injectable so tests can enforce append-only API behavior
// against real Git histories without touching GitHub branches.
export function updateRelease({ repository, source, tree, git, api = github }) {
  const branch = 'changeset-release/dev';
  const repo = `repos/${repository}`;
  const text = (...args) =>
    git(...args)
      .toString()
      .trim();
  const paths = (from, to, filter) =>
    git(
      'diff',
      '--name-only',
      '--no-renames',
      '-z',
      `--diff-filter=${filter}`,
      from,
      to
    )
      .toString()
      .split('\0')
      .filter(Boolean);

  function appendTree(head, target, headline) {
    const additions = paths(head, target, 'ACMT').map((path) => ({
      path,
      contents: Buffer.from(git('show', `${target}:${path}`)).toString(
        'base64'
      ),
    }));
    const deletions = paths(head, target, 'D').map((path) => ({ path }));
    if (!additions.length && !deletions.length) return head;

    const response = api('POST', 'graphql', {
      query: commitMutation,
      variables: {
        input: {
          branch: { repositoryNameWithOwner: repository, branchName: branch },
          expectedHeadOid: head,
          message: { headline },
          fileChanges: { additions, deletions },
        },
      },
    });
    const commit = response.data.createCommitOnBranch.commit;
    if (!commit.signature?.isValid) {
      throw new Error('GitHub did not verify the release commit signature');
    }
    return commit.oid;
  }

  const refs = api('GET', `${repo}/git/matching-refs/heads/${branch}`);
  let head = refs.find((ref) => ref.ref === `refs/heads/${branch}`)?.object.sha;
  if (!head) {
    api('POST', `${repo}/git/refs`, {
      ref: `refs/heads/${branch}`,
      sha: source,
    });
    head = source;
  } else {
    git('fetch', 'origin', branch);
    const base = text('merge-base', source, head);
    // A rerun with the same generated tree and dev ancestry needs no commits.
    if (base !== source || text('rev-parse', `${head}^{tree}`) !== tree) {
      // Undo the previous generated files with a new signed commit. Restoring
      // the common ancestor's tree makes the following merge conflict-free,
      // while retaining every existing release commit in branch history.
      appendTree(head, base, 'Prepare release branch for current dev');
      api('POST', `${repo}/merges`, {
        base: branch,
        head: source,
        commit_message: 'Merge dev into release branch',
      });
      head = api('GET', `${repo}/git/ref/heads/${branch}`).object.sha;
      git('fetch', 'origin', branch);
      if (
        text('rev-parse', `${head}^{tree}`) !==
        text('rev-parse', `${source}^{tree}`)
      ) {
        throw new Error(
          'Release branch changed unexpectedly while merging dev'
        );
      }
    }
  }

  appendTree(head, tree, 'Version Packages');
  const params = new URLSearchParams({
    state: 'open',
    base: 'dev',
    head: `${repository.split('/')[0]}:${branch}`,
  });
  const [existing] = api('GET', `${repo}/pulls?${params}`);
  const details = {
    title: 'Version Packages',
    body: 'Updates package versions and CHANGELOG from the pending changesets on dev.\n\nGenerated by the append-only Release workflow using GitHub-signed commits.',
    base: 'dev',
  };
  const pullRequest = existing
    ? api('PATCH', `${repo}/pulls/${existing.number}`, details)
    : api('POST', `${repo}/pulls`, { ...details, head: branch });
  return pullRequest.html_url;
}

function main() {
  const repository = process.env.GH_REPO;
  if (!repository || process.env.GITHUB_REF !== 'refs/heads/dev') {
    throw new Error('Release must run on dev with GH_REPO configured');
  }
  const git = (...args) => execute('git', args);
  if (git('status', '--porcelain').toString().trim()) {
    throw new Error('Release requires a clean working tree');
  }
  const source = git('rev-parse', 'HEAD').toString().trim();
  const directory = mkdtempSync(join(tmpdir(), 'maze-release-'));
  try {
    const statusPath = join(directory, 'status.json');
    // CLI v2 joins --output to cwd, even when given an absolute path.
    execute('bun', [
      'run',
      'changeset',
      'status',
      '--output',
      relative(process.cwd(), statusPath),
    ]);
    const status = JSON.parse(readFileSync(statusPath, 'utf8'));
    if (!status.releases.length) {
      process.stdout.write('No pending releases.\n');
      return;
    }
    // Invoke the installed CLI explicitly through Bun; never fall back to npm.
    execute('bun', ['run', 'changeset', 'version']);
    execute('bun', ['install', '--lockfile-only']);
    git('add', '--all');
    const tree = git('write-tree').toString().trim();
    const url = updateRelease({ repository, source, tree, git });
    process.stdout.write(`${url}\n`);
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
}

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  main();
}
